#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. See LOCAL_math_builtin_functions.md. */
enum { NR = 6, NK = 6 };

/* RTDS lifecycle placement generated from final-expression dependency analysis.
   RAM_PASS1 stamps only RAM_CONSTANT Gred entries through g_mat_over.
   CODE/BEGIN_T0 computes only dynamic reduced-G and non-direct Ihisred paths.
   T1_T2 reads solved node voltages and recovers eliminated-node voltages when needed. */
STATIC:
    /* Runtime matrix objects */
    MATRIX_ Grr_code = {0};
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ W_code = {0};
    MATRIX_ D = {0};
    MATRIX_ U = {0};
    MATRIX_ S = {0};
    MATRIX_ inv_D = {0};
    MATRIX_ U_T = {0};
    MATRIX_ tmp_UT_invD = {0};
    MATRIX_ tmp_UT_invD_U = {0};
    MATRIX_ M = {0};
    MATRIX_ M_inv = {0};
    MATRIX_ tmp_Dinv_U = {0};
    MATRIX_ tmp_Dinv_U_Minv = {0};
    MATRIX_ tmp_Dinv_U_Minv_UT = {0};
    MATRIX_ tmp_Dinv_U_Minv_UT_Dinv = {0};
    MATRIX_ W_DD = {0};
    MATRIX_ W_DS = {0};
    MATRIX_ tmp_Minv_UT = {0};
    MATRIX_ W_SD = {0};
    MATRIX_ W_SS = {0};
    MATRIX_ Gred_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    MATRIX_ tmp_Grk_W_code = {0};
    MATRIX_ tmp_Grk_W_Gkr_code = {0};
    MATRIX_ tmp_Grk_W_Ihisk_code = {0};
    MATRIX_ tmp_W_Gkr_code = {0};
    MATRIX_ tmp_W_Gkr_Vr_code = {0};
    MATRIX_ tmp_W_Ihisk_code = {0};
    MATRIX_ tmp_Vk_sum_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double AN = 0.0;
    double AP = 0.0;
    double BN = 0.0;
    double BP = 0.0;
    double CN = 0.0;
    double CP = 0.0;
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double PN = 0.0;
    double PP = 0.0;
    double gNN = 0.0;
    double w1 = 0.0;
    double w2 = 0.0;
    /* User Ihis/history symbols */
    double Dabc = 0.0;
    double Grc = 0.0;
    double IAhis_rc = 0.0;
    double IBhis_rc = 0.0;
    double IC_his0 = 0.0;
    double IChis_rc = 0.0;
    double Ihis_A = 0.0;
    double Ihis_B = 0.0;
    double Ihis_C = 0.0;
    double Ihis_a = 0.0;
    double Ihis_b = 0.0;
    double Ihis_c = 0.0;
    double Ihis_exclude_c0 = 0.0;
    double Ihis_exclude_c1 = 0.0;
    double Ihis_exclude_c2 = 0.0;
    double Ihis_exclude_c3 = 0.0;
    double Ihis_exclude_c4 = 0.0;
    /* Block-matrix scalar aliases */
    double Gkr_k4_N = 0.0;
    double Gkr_k4_P = 0.0;
    double Gkr_k5_N = 0.0;
    double Gkr_k5_P = 0.0;
    double Gkr_k6_N = 0.0;
    double Gkr_k6_P = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Gkr_shared_3 = 0.0;
    double Grk_N_k4 = 0.0;
    double Grk_N_k5 = 0.0;
    double Grk_N_k6 = 0.0;
    double Grk_P_k4 = 0.0;
    double Grk_P_k5 = 0.0;
    double Grk_P_k6 = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;
    double Grk_shared_3 = 0.0;
    double Grr_G_G = 0.0;
    double Grr_N_N = 0.0;
    double Grr_P_P = 0.0;
    double Grr_shared_1 = 0.0;
    double Grr_shared_2 = 0.0;
    double Grr_shared_3 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double gC = 0.0;

RAM_PASS1:
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "P");
    g_mat_nods[1] = getNodeNum(comp, "N");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (int row = 0; row < 2; row++) {
        for (int col = 0; col < 2; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    g_mat_over[0][0] = gC;
    g_mat_over[0][1] = -gC;
    g_mat_over[1][0] = -gC;
    g_mat_over[1][1] = gC;
    setupGMatrix(2);

    err += matrixDim(&Grr_code, NR, NR);
    err += matrixDim(&Grk_code, NR, NK);
    err += matrixDim(&Gkr_code, NK, NR);
    err += matrixDim(&W_code, NK, NK);
    err += matrixDim(&D, 4, 4);
    err += matrixDim(&U, 4, 2);
    err += matrixDim(&S, 2, 2);
    err += matrixDim(&inv_D, 4, 4);
    err += matrixDim(&U_T, 2, 4);
    err += matrixDim(&tmp_UT_invD, 2, 4);
    err += matrixDim(&tmp_UT_invD_U, 2, 2);
    err += matrixDim(&M, 2, 2);
    err += matrixDim(&M_inv, 2, 2);
    err += matrixDim(&tmp_Dinv_U, 4, 2);
    err += matrixDim(&tmp_Dinv_U_Minv, 4, 2);
    err += matrixDim(&tmp_Dinv_U_Minv_UT, 4, 4);
    err += matrixDim(&tmp_Dinv_U_Minv_UT_Dinv, 4, 4);
    err += matrixDim(&W_DD, 4, 4);
    err += matrixDim(&W_DS, 4, 2);
    err += matrixDim(&tmp_Minv_UT, 2, 4);
    err += matrixDim(&W_SD, 2, 4);
    err += matrixDim(&W_SS, 2, 2);
    err += matrixDim(&Gred_code, NR, NR);
    err += matrixDim(&Ihisr_code, NR, 1);
    err += matrixDim(&Ihisk_code, NK, 1);
    err += matrixDim(&Ihisred_code, NR, 1);
    err += matrixDim(&Vr_code, NR, 1);
    err += matrixDim(&Vk_code, NK, 1);
    err += matrixDim(&tmp_Grk_W_code, NR, NK);
    err += matrixDim(&tmp_Grk_W_Gkr_code, NR, NR);
    err += matrixDim(&tmp_Grk_W_Ihisk_code, NR, 1);
    err += matrixDim(&tmp_W_Gkr_code, NK, NR);
    err += matrixDim(&tmp_W_Gkr_Vr_code, NK, 1);
    err += matrixDim(&tmp_W_Ihisk_code, NK, 1);
    err += matrixDim(&tmp_Vk_sum_code, NK, 1);
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }
    matrix_register(&Grr_code);
    matrix_register(&Grk_code);
    matrix_register(&Gkr_code);
    matrix_register(&W_code);
    matrix_register(&Gred_code);
    matrix_register(&D);
    matrix_register(&U);
    matrix_register(&Ihisred_code);
    matrix_register(&S);
    matrix_register(&inv_D);
    matrix_register(&tmp_Grk_W_code);
    matrix_register(&tmp_Grk_W_Gkr_code);
    matrix_register(&tmp_Grk_W_Ihisk_code);
    matrix_register(&U_T);
    matrix_register(&tmp_UT_invD);
    matrix_register(&tmp_UT_invD_U);
    matrix_register(&M);
    matrix_register(&M_inv);
    matrix_register(&tmp_Dinv_U);
    matrix_register(&tmp_Dinv_U_Minv);
    matrix_register(&tmp_Dinv_U_Minv_UT);
    matrix_register(&tmp_Dinv_U_Minv_UT_Dinv);
    matrix_register(&W_DD);
    matrix_register(&W_DS);
    matrix_register(&tmp_Minv_UT);
    matrix_register(&W_SD);
    matrix_register(&W_SS);
    matrix_register(&Ihisr_code);
    matrix_register(&Ihisk_code);
    matrix_register(&Vr_code);
    matrix_register(&Vk_code);
    matrix_register(&tmp_W_Gkr_code);
    matrix_register(&tmp_W_Gkr_Vr_code);
    matrix_register(&tmp_W_Ihisk_code);
    matrix_register(&tmp_Vk_sum_code);

GVALUES:
    /* Dynamic reduced-G stamp handles, ordered by Gred upper triangle. */
    double varG_A_1_A_1 = createGValue("varG_A_1_A_1", "A_1", "A_1", 0, "TRUE");
    double varG_A_1_B_1 = createGValue("varG_A_1_B_1", "A_1", "B_1", 0, "TRUE");
    double varG_A_1_C_1 = createGValue("varG_A_1_C_1", "A_1", "C_1", 0, "TRUE");
    double varG_A_1_G = createGValue("varG_A_1_G", "A_1", "G", 0, "TRUE");
    double varG_A_1_P = createGValue("varG_A_1_P", "A_1", "P", 0, "TRUE");
    double varG_A_1_N = createGValue("varG_A_1_N", "A_1", "N", 0, "TRUE");
    double varG_B_1_B_1 = createGValue("varG_B_1_B_1", "B_1", "B_1", 0, "TRUE");
    double varG_B_1_C_1 = createGValue("varG_B_1_C_1", "B_1", "C_1", 0, "TRUE");
    double varG_B_1_G = createGValue("varG_B_1_G", "B_1", "G", 0, "TRUE");
    double varG_B_1_P = createGValue("varG_B_1_P", "B_1", "P", 0, "TRUE");
    double varG_B_1_N = createGValue("varG_B_1_N", "B_1", "N", 0, "TRUE");
    double varG_C_1_C_1 = createGValue("varG_C_1_C_1", "C_1", "C_1", 0, "TRUE");
    double varG_C_1_G = createGValue("varG_C_1_G", "C_1", "G", 0, "TRUE");
    double varG_C_1_P = createGValue("varG_C_1_P", "C_1", "P", 0, "TRUE");
    double varG_C_1_N = createGValue("varG_C_1_N", "C_1", "N", 0, "TRUE");
    double varG_G_G = createGValue("varG_G_G", "G", "G", 0, "TRUE");
    double varG_G_P = createGValue("varG_G_P", "G", "P", 0, "TRUE");
    double varG_G_N = createGValue("varG_G_N", "G", "N", 0, "TRUE");
    double varG_P_P = createGValue("varG_P_P", "P", "P", 0, "TRUE");
    double varG_P_N = createGValue("varG_P_N", "P", "N", 0, "TRUE");
    double varG_N_N = createGValue("varG_N_N", "N", "N", 0, "TRUE");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grr_code);
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&W_code);
        conditionMatrixForCODE(&Gred_code);
        conditionMatrixForCODE(&D);
        conditionMatrixForCODE(&U);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&S);
        conditionMatrixForCODE(&inv_D);
        conditionMatrixForCODE(&tmp_Grk_W_code);
        conditionMatrixForCODE(&tmp_Grk_W_Gkr_code);
        conditionMatrixForCODE(&tmp_Grk_W_Ihisk_code);
        conditionMatrixForCODE(&U_T);
        conditionMatrixForCODE(&tmp_UT_invD);
        conditionMatrixForCODE(&tmp_UT_invD_U);
        conditionMatrixForCODE(&M);
        conditionMatrixForCODE(&M_inv);
        conditionMatrixForCODE(&tmp_Dinv_U);
        conditionMatrixForCODE(&tmp_Dinv_U_Minv);
        conditionMatrixForCODE(&tmp_Dinv_U_Minv_UT);
        conditionMatrixForCODE(&tmp_Dinv_U_Minv_UT_Dinv);
        conditionMatrixForCODE(&W_DD);
        conditionMatrixForCODE(&W_DS);
        conditionMatrixForCODE(&tmp_Minv_UT);
        conditionMatrixForCODE(&W_SD);
        conditionMatrixForCODE(&W_SS);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&Vk_code);
        conditionMatrixForCODE(&tmp_W_Gkr_code);
        conditionMatrixForCODE(&tmp_W_Gkr_Vr_code);
        conditionMatrixForCODE(&tmp_W_Ihisk_code);
        conditionMatrixForCODE(&tmp_Vk_sum_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */



    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
    /* Grr_shared_1 represents Grr[A_1,A_1], Grr[B_1,B_1], Grr[C_1,C_1]: 2.0*G11 + 2.0*w1. */
    Grr_shared_1 = 2.0*G11 + 2.0*w1;
    /* Grr_shared_2 represents Grr[A_1,B_1], Grr[A_1,C_1], Grr[B_1,A_1], Grr[B_1,C_1], Grr[C_1,A_1], Grr[C_1,B_1]: -G11 - w1. */
    Grr_shared_2 = -G11 - w1;
    /* Grr_G_G represents Grr[G,G]: 3.0*G22 + 3.0*w2. */
    Grr_G_G = 3.0*G22 + 3.0*w2;
    /* Grr_P_P represents Grr[P,P]: PP. */
    Grr_P_P = PP;
    /* Grr_shared_3 represents Grr[P,N], Grr[N,P]: PN. */
    Grr_shared_3 = PN;
    /* Grr_N_N represents Grr[N,N]: gNN. */
    Grr_N_N = gNN;
    /* Grk_shared_1 represents Grk[A_1,k4], Grk[B_1,k5], Grk[C_1,k6]: -G12. */
    Grk_shared_1 = -G12;
    /* Grk_shared_2 represents Grk[A_1,k5], Grk[B_1,k6], Grk[C_1,k4]: G12. */
    Grk_shared_2 = G12;
    /* Grk_shared_3 represents Grk[G,k4], Grk[G,k5], Grk[G,k6]: -G22 - w2. */
    Grk_shared_3 = -G22 - w2;
    /* Grk_P_k4 represents Grk[P,k4]: CP. */
    Grk_P_k4 = CP;
    /* Grk_P_k5 represents Grk[P,k5]: AP. */
    Grk_P_k5 = AP;
    /* Grk_P_k6 represents Grk[P,k6]: BP. */
    Grk_P_k6 = BP;
    /* Grk_N_k4 represents Grk[N,k4]: CN. */
    Grk_N_k4 = CN;
    /* Grk_N_k5 represents Grk[N,k5]: AN. */
    Grk_N_k5 = AN;
    /* Grk_N_k6 represents Grk[N,k6]: BN. */
    Grk_N_k6 = BN;
    /* Gkr_shared_1 represents Gkr[k4,A_1], Gkr[k5,B_1], Gkr[k6,C_1]: -G12. */
    Gkr_shared_1 = -G12;
    /* Gkr_shared_2 represents Gkr[k4,C_1], Gkr[k5,A_1], Gkr[k6,B_1]: G12. */
    Gkr_shared_2 = G12;
    /* Gkr_shared_3 represents Gkr[k4,G], Gkr[k5,G], Gkr[k6,G]: -G22 - w2. */
    Gkr_shared_3 = -G22 - w2;
    /* Gkr_k4_P represents Gkr[k4,P]: CP. */
    Gkr_k4_P = CP;
    /* Gkr_k4_N represents Gkr[k4,N]: CN. */
    Gkr_k4_N = CN;
    /* Gkr_k5_P represents Gkr[k5,P]: AP. */
    Gkr_k5_P = AP;
    /* Gkr_k5_N represents Gkr[k5,N]: AN. */
    Gkr_k5_N = AN;
    /* Gkr_k6_P represents Gkr[k6,P]: BP. */
    Gkr_k6_P = BP;
    /* Gkr_k6_N represents Gkr[k6,N]: BN. */
    Gkr_k6_N = BN;
    set_CODE(&Grr_code, 0, 0, Grr_shared_1);
    set_CODE(&Grr_code, 1, 1, Grr_shared_1);
    set_CODE(&Grr_code, 2, 2, Grr_shared_1);
    set_CODE(&Grr_code, 0, 1, Grr_shared_2);
    set_CODE(&Grr_code, 0, 2, Grr_shared_2);
    set_CODE(&Grr_code, 1, 0, Grr_shared_2);
    set_CODE(&Grr_code, 1, 2, Grr_shared_2);
    set_CODE(&Grr_code, 2, 0, Grr_shared_2);
    set_CODE(&Grr_code, 2, 1, Grr_shared_2);
    set_CODE(&Grr_code, 3, 3, Grr_G_G);
    set_CODE(&Grr_code, 4, 4, Grr_P_P);
    set_CODE(&Grr_code, 4, 5, Grr_shared_3);
    set_CODE(&Grr_code, 5, 4, Grr_shared_3);
    set_CODE(&Grr_code, 5, 5, Grr_N_N);
    set_CODE(&Grk_code, 0, 3, Grk_shared_1);
    set_CODE(&Grk_code, 1, 4, Grk_shared_1);
    set_CODE(&Grk_code, 2, 5, Grk_shared_1);
    set_CODE(&Grk_code, 0, 4, Grk_shared_2);
    set_CODE(&Grk_code, 1, 5, Grk_shared_2);
    set_CODE(&Grk_code, 2, 3, Grk_shared_2);
    set_CODE(&Grk_code, 3, 3, Grk_shared_3);
    set_CODE(&Grk_code, 3, 4, Grk_shared_3);
    set_CODE(&Grk_code, 3, 5, Grk_shared_3);
    set_CODE(&Grk_code, 4, 3, Grk_P_k4);
    set_CODE(&Grk_code, 4, 4, Grk_P_k5);
    set_CODE(&Grk_code, 4, 5, Grk_P_k6);
    set_CODE(&Grk_code, 5, 3, Grk_N_k4);
    set_CODE(&Grk_code, 5, 4, Grk_N_k5);
    set_CODE(&Grk_code, 5, 5, Grk_N_k6);
    set_CODE(&Gkr_code, 3, 0, Gkr_shared_1);
    set_CODE(&Gkr_code, 4, 1, Gkr_shared_1);
    set_CODE(&Gkr_code, 5, 2, Gkr_shared_1);
    set_CODE(&Gkr_code, 3, 2, Gkr_shared_2);
    set_CODE(&Gkr_code, 4, 0, Gkr_shared_2);
    set_CODE(&Gkr_code, 5, 1, Gkr_shared_2);
    set_CODE(&Gkr_code, 3, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 4, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 5, 3, Gkr_shared_3);
